const viewInformation={
  traditional:{intro:'Die herkömmliche Darstellung verbindet die Lage im Periodensystem mit einer verbreiteten stofflichen Einordnung. Sie eignet sich zur ersten Orientierung, ist aber kein einzelnes naturwissenschaftliches Messmodell.',physics:'Metalle, Halbmetalle und Nichtmetalle unterscheiden sich unter anderem durch Leitfähigkeit und Bandstruktur. Die Gruppenlage spiegelt wiederkehrende Eigenschaften der Elektronenhülle.',chemistry:'Elemente derselben Hauptgruppe besitzen ähnliche Valenzelektronenkonfigurationen. Daraus folgen verwandte Bindungsarten, Oxidationszahlen und Reaktivitätstrends.',math:'Die Rasterposition ist diskret: Periode = höchste besetzte Hauptschale; bei Hauptgruppenelementen hängt die Gruppe eng mit der Zahl der Valenzelektronen zusammen.',limits:'Kategorien besitzen Grenzfälle und sind keine Messwerte. Je nach Lehrbuch können einzelne Halbmetalle oder Übergangselemente anders eingeordnet werden.'},
  'material-class':{intro:'Diese Ansicht reduziert die Elemente bewusst auf Metalle, Halbmetalle und Nichtmetalle.',physics:'Entscheidend sind elektrische Leitfähigkeit, Temperaturabhängigkeit der Leitfähigkeit und die elektronische Bandstruktur. Halbmetalle liegen zwischen typischen Leitern und Nichtleitern.',chemistry:'Metalle geben in Verbindungen häufig Elektronen ab, Nichtmetalle nehmen sie auf oder teilen sie in kovalenten Bindungen. Das ist eine Tendenz, keine ausnahmslose Regel.',math:'Die Darstellung ist eine kategoriale Zuordnung und keine kontinuierliche Skala. Eine physikalische Vertiefung würde Bandlücke und Leitfähigkeit quantitativ vergleichen.',limits:'Die Grenze der Halbmetalle ist fachlich nicht eindeutig; diese App folgt dem dokumentierten EduChem-orientierten Modell.'},
  family:{intro:'Elementfamilien gruppieren Elemente mit ähnlichem chemischem Verhalten und ergänzen die rein geometrische Gruppenordnung.',physics:'Ähnliche Außenelektronenstrukturen führen zu verwandten Ionisierungsenergien, Atomradien und Leitfähigkeitseigenschaften.',chemistry:'Alkalimetalle, Erdalkalimetalle, Chalkogene, Halogene und Edelgase folgen besonders deutlich gemeinsamen Valenzelektronenmustern. Platin- und Münzmetalle sind anwendungsbezogene Untergruppen.',math:'Familien sind Mengen von Ordnungszahlen. Manche Mengen überschneiden sich fachlich, weshalb die Visualisierung eine festgelegte Prioritätsregel verwendet.',limits:'„Seltene Erden“, „Platinmetalle“ und „Münzmetalle“ folgen nicht alle derselben systematischen Klassifikationslogik.'},
  state:{intro:'Die Ansicht berechnet den Aggregatzustand für die eingestellte Temperatur und den Druck aus hinterlegten Phasendaten.',physics:'Fest, flüssig und gasförmig sind Bereiche eines Phasendiagramms. Phasengrenzen hängen von Temperatur und Druck ab; Helium sowie Sublimationsfälle benötigen Sonderregeln.',chemistry:'Schmelzen und Verdampfen verändern den Stoffzustand, nicht die chemische Identität. Zwischenmolekulare beziehungsweise metallische Kräfte bestimmen die nötige Energie.',math:'Nahe den Referenzbedingungen wird die Druckverschiebung des Siedepunkts näherungsweise mit ln(P₂/P₁) = −ΔH<sub>vap</sub>/R · (1/T₂ − 1/T₁) berechnet.',limits:'Die Berechnung ersetzt kein vollständiges Phasendiagramm. Hochdruckphasen, Allotrope und fehlende Messdaten sind nur vereinfacht oder als unbekannt abgebildet.'},
  'electronegativity-pauling':{intro:'Die Pauling-Skala beschreibt, wie stark ein gebundenes Atom gemeinsame Elektronen anzieht.',physics:'Die Skala wird aus zusätzlichen Bindungsenergien abgeleitet und ist relativ sowie dimensionslos. Fluor bildet mit 3,98 den oberen Referenzbereich.',chemistry:'Elektronegativitätsdifferenzen helfen, Bindungspolarität und Ladungsverteilung abzuschätzen. Sie legen den Bindungstyp nicht allein fest.',math:'Pauling verknüpft die Differenz Δχ mit der Differenz zwischen gemessener heteronuklearer und erwarteter Bindungsenergie; die genaue Normierung ist skalenabhängig.',limits:'Werte hängen von Bindungssituation und Oxidationszustand ab. Fehlende Werte werden neutral und nicht als Null dargestellt.'},
  'electronegativity-allred':{intro:'Allred–Rochow schätzt Elektronegativität aus der elektrostatischen Anziehung des Atomrumpfs auf Valenzelektronen.',physics:'Wirksam sind die effektive Kernladung Z<sub>eff</sub> und der kovalente Radius r. Größere Kernladung erhöht, größerer Radius vermindert die Anziehung.',chemistry:'Das Modell verbindet Periodentrends anschaulich mit Abschirmung und Atomgröße.',math:'χ<sub>AR</sub> = 0,359 · Z<sub>eff</sub>/r² + 0,744 (in der üblichen Parametrisierung der Skala).',limits:'Z<sub>eff</sub> und Radius sind modell- beziehungsweise umgebungsabhängig; die Skala ist nicht mit Pauling-Werten identisch.'},
  'electronegativity-mulliken':{intro:'Die Mulliken-Elektronegativität mittelt die Energie zum Entfernen und die Energiebilanz zum Aufnehmen eines Elektrons.',physics:'Ionisierungsenergie IE und Elektronenaffinität EA beziehen sich auf isolierte gasförmige Atome.',chemistry:'Ein hoher Mittelwert kennzeichnet Atome, die Elektronendichte energetisch stark binden.',math:'χ<sub>M</sub> = (IE + EA) / 2. In dieser App wird das Ergebnis in Elektronenvolt (eV) geführt.',limits:'Die dimensionsbehaftete Mulliken-Skala darf nicht unmittelbar wie eine dimensionslose Pauling-Zahl gelesen werden.'},
  resistivity:{intro:'Der spezifische elektrische Widerstand beschreibt, wie stark ein Material den elektrischen Stromfluss hemmt.',physics:'Er hängt von Temperatur, Kristallstruktur, Reinheit und Aggregatzustand ab. Metalle besitzen meist kleine, Nichtmetalle sehr große Werte.',chemistry:'Bindungsart und Bandstruktur entscheiden darüber, ob bewegliche Ladungsträger verfügbar sind.',math:'ρ = R · A / l; Einheit Ω·m. Wegen vieler Größenordnungen verwendet die Farbklassifikation eine logarithmische Skala.',limits:'Die dargestellten Werte beziehen sich soweit verfügbar auf Raumtemperatur und idealisierte Stoffproben.'},
  density:{intro:'Dichte vergleicht Masse und Volumen eines Stoffes und macht sehr leichte sowie sehr schwere Elemente sichtbar.',physics:'Dichte hängt von Temperatur, Druck, Aggregatzustand und Kristallstruktur ab.',chemistry:'Hohe Atommasse allein garantiert keine hohe Dichte; auch Packung, Bindung und Atomradius wirken mit.',math:'ρ = m/V. Die App verwendet g/cm³ und ordnet die Werte in beschriftete Größenklassen ein.',limits:'Allotrope können deutlich verschiedene Dichten besitzen. Fehlende belastbare Referenzwerte bleiben neutral.'},
  discovery:{intro:'Die Zeitleiste zeigt, welche Elemente zu einem gewählten historischen Zeitpunkt bereits bekannt waren und welche neu hinzukamen.',physics:'Neue Messverfahren – Spektroskopie, Elektrolyse und Kernreaktionen – erschlossen jeweils andere Elementgruppen.',chemistry:'„Entdeckung“ kann Isolierung, Identifikation oder anerkannte Beschreibung bedeuten und ist historisch nicht immer eindeutig.',math:'Der Regler verwendet diskrete, tatsächlich hinterlegte Entdeckungsjahre. Die Ansicht ist ordinal-chronologisch, nicht proportional zur Zahl der Entdeckungen.',limits:'Antike Elemente besitzen kein einzelnes Entdeckungsjahr; bei Prioritätsstreitigkeiten folgt die App dem dokumentierten Datensatz.'},
  'abundance-crust':{intro:'Die Ansicht zeigt Massenanteile der Elemente in der Erdhülle beziehungsweise Erdkruste.',physics:'Gravitative Differentiation, Mineralbildung und geologische Prozesse verändern die Zusammensetzung gegenüber der Gesamterde.',chemistry:'Sauerstoff und Silicium dominieren viele gesteinsbildende Minerale; chemische Affinitäten steuern die Bindung in Mineralphasen.',math:'Massenanteil wᵢ = mᵢ/m<sub>gesamt</sub> · 100 %. Die Farbstufen folgen Zehnerpotenzen und damit einer logarithmischen Ordnung.',limits:'Regionale Gesteine weichen stark vom globalen Mittel ab. „Nicht quantifiziert“ bedeutet nicht „nicht vorhanden“.'},
  'abundance-earth':{intro:'Diese Ansicht schätzt die Massenanteile in der gesamten Erde einschließlich Kern, Mantel und Kruste.',physics:'Dichte und planetare Differentiation konzentrierten siderophile Elemente im Kern und leichtere Silikate im Mantel.',chemistry:'Eisen, Sauerstoff, Silicium und Magnesium prägen die Gesamtzusammensetzung, aber in unterschiedlichen chemischen Phasen.',math:'Massenanteile werden in Prozent und logarithmischen Zehnerpotenzklassen dargestellt.',limits:'Das Erdinnere ist nicht direkt vollständig beprobbar; Werte beruhen auf geophysikalischen und kosmochemischen Modellen.'},
  'abundance-ocean':{intro:'Die Ozeanansicht zeigt Elementanteile im Meerwasser und damit ein gelöstes, dynamisches Stoffsystem.',physics:'Verdunstung, Zuflüsse, Sedimentation und hydrothermale Prozesse beeinflussen Konzentrationen.',chemistry:'Elemente liegen überwiegend als Wasser, Ionen oder gelöste Verbindungen vor; ihre Elementsumme ist nicht mit der Konzentration einzelner Salze gleichzusetzen.',math:'Die Farbklassen beruhen auf Massenanteilen wᵢ in Prozent und sind logarithmisch abgestuft.',limits:'Salinität und Zusammensetzung unterscheiden sich regional und mit der Tiefe; Spurenelemente können biologisch wichtig sein.'},
  body:{intro:'Die Ansicht ordnet Elemente nach ihrer mengenmäßigen und funktionellen Bedeutung für den menschlichen Körper.',physics:'Die Darstellung betrifft Stoffmengen im Organismus, nicht die Eigenschaften reiner Elementstoffe.',chemistry:'H, C, N, O, P und S bilden zentrale Biomoleküle; weitere Elemente wirken als Elektrolyte, Struktur- oder Spurenelemente.',math:'Die Kategorien sind qualitative beziehungsweise größenklassenartige Mengenstufen, keine stöchiometrische Summenformel des Menschen.',limits:'Bedarf und Konzentration variieren. Eine biologische Rolle darf nicht mit der Gefahrlosigkeit des reinen Elements verwechselt werden.'},
  life:{intro:'Diese Ansicht erweitert den Blick auf Elemente mit gesicherter oder vermuteter Bedeutung für Lebewesen.',physics:'Verfügbarkeit hängt von Umwelt, Löslichkeit und Transportmechanismen ab.',chemistry:'Elemente können Bausteine, Cofaktoren oder Redoxzentren sein. Die biologische Funktion beruht fast immer auf Verbindungen oder Ionen.',math:'Die Zuordnung ist kategorial; sie bildet keine einheitliche Konzentrationsskala über alle Organismen.',limits:'Biologische Bedeutung ist artspezifisch. Vermutete Funktionen werden nicht als allgemein gesichert behandelt.'},
  origin:{intro:'Die Ansicht zeigt modellierte Beiträge verschiedener kosmischer Nukleosyntheseprozesse zur heutigen Elementhäufigkeit im Sonnensystem.',physics:'Urknall, Sternfusion, Supernovae, Neutronensternverschmelzungen und kosmische Strahlung erzeugen unterschiedliche Nuklide.',chemistry:'Die chemische Elementsorte wird durch die Protonenzahl bestimmt; kosmische Prozesse erzeugen zunächst Isotope, deren Beiträge hier elementweise zusammengefasst werden.',math:'Die farbigen Flächen einer Kachel sind prozentuale Anteile; idealisiert gilt Σpᵢ ≈ 100 %. Rundung und Modellunsicherheit können kleine Abweichungen erzeugen.',limits:'Die Anteile sind wissenschaftliche Modellschätzungen, keine direkt gemessenen Herkunftsetiketten einzelner Atome.'}
};

function infoCard(title,text,formula=''){return`<section class="info-card"><h3>${title}</h3><p>${text}</p>${formula?`<p class="info-formula">${formula}</p>`:''}</section>`}
function openViewInformation(){const content=viewInformation[settings.view]??viewInformation.traditional;const title=viewTitles[settings.view]??'Herkömmliche Darstellung';infoDialogTitle.textContent=title;infoDialogBody.innerHTML=`<p class="info-intro">${content.intro}</p><div class="info-grid">${infoCard('Physikalische Grundlage',content.physics)}${infoCard('Chemische Bedeutung',content.chemistry)}${infoCard('Mathematische Darstellung',content.math)}<section class="info-card info-note"><h3>Einordnung und Grenzen</h3><p>${content.limits}</p></section></div>`;infoDialog.showModal()}

function categoryClass(element){return `category-${element.category}`}
function materialClass(element){const metalloids=new Set([5,14,32,33,51,52,85,117,118]);if(metalloids.has(element.number))return'metalloid';const nonmetals=new Set([1,2,6,7,8,9,10,15,16,17,18,34,35,36,53,54,86]);return nonmetals.has(element.number)?'nonmetal':'metal'}
function familyClass(element){if([29,47,79].includes(element.number))return'coinage';if([44,45,46,76,77,78].includes(element.number))return'platinum';if([21,39,...Array.from({length:15},(_,index)=>index+57)].includes(element.number))return'rare-earth';if(element.number>=89&&element.number<=103)return'actinide';if(element.group===1&&element.number!==1)return'alkali';if(element.group===2)return'alkaline';if(element.group===16)return'chalcogen';if(element.group===17)return'halogen';if(element.group===18)return'noble';return'other'}
function isRadioactiveElement(element){return element.number===43||element.number===61||element.number>=83}
function tileName(element){return settings.nameMode==='origin'?(nameData?.symbolNames?.[element.number]??element.name):element.name}
function symbolOrigin(element){const name=nameData?.symbolNames?.[element.number]??element.name;const language=nameData?.symbolLanguages?.[element.number]??'engl.';return`${element.symbol} (${language} ${name})`}
const nobleGasShells={He:[2],Ne:[2,8],Ar:[2,8,8],Kr:[2,8,18,8],Xe:[2,8,18,18,8],Rn:[2,8,18,32,18,8]};
const nobleGasConfigurations={He:'1s2',Ne:'1s2 2s2 2p6',Ar:'1s2 2s2 2p6 3s2 3p6',Kr:'1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6',Xe:'1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6 5s2 4d10 5p6',Rn:'1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6 5s2 4d10 5p6 6s2 4f14 5d10 6p6'};
function shellDistribution(configuration){const shells=[];const core=configuration.match(/^\[([A-Za-z]+)\]/)?.[1];if(core)nobleGasShells[core]?.forEach((count,index)=>shells[index]=count);for(const match of configuration.matchAll(/(\d)([spdfg])(\d+)/g)){const shell=Number(match[1])-1;shells[shell]=(shells[shell]??0)+Number(match[3])}return shells.map(value=>value??0)}
function elementTileMarkup(element){return`<span class="detail-number">${element.number}</span><strong class="detail-symbol">${element.symbol}</strong><span class="detail-name">${element.name}</span>`}
function atomModelMarkup(element,configuration){const shells=shellDistribution(configuration);const center=190;const shellGap=Math.min(22,145/Math.max(shells.length,1));const shellSvg=shells.map((count,index)=>{const radius=25+(index*shellGap);const electrons=Array.from({length:count},(_,electron)=>{const angle=(-Math.PI/2)+(electron/count*Math.PI*2);return`<circle class="atom-electron" cx="${center+Math.cos(angle)*radius}" cy="${center+Math.sin(angle)*radius}" r="3.5"/>`}).join('');return`<circle class="atom-shell" cx="${center}" cy="${center}" r="${radius}"/>${electrons}`}).join('');return`<svg class="atom-model" viewBox="0 0 380 380" role="img" aria-label="Bohrsches Schalenmodell von ${element.name}: ${shells.join(', ')} Elektronen je Schale">${shellSvg}<circle class="atom-nucleus" cx="190" cy="190" r="19"/><text x="190" y="190" dy=".35em">${element.symbol}</text></svg><span class="atom-caption">${shells.join(' · ')} Elektronen</span>`}
function expandedSubshells(configuration){const core=configuration.match(/^\[([A-Za-z]+)\]/)?.[1];const expanded=`${core?nobleGasConfigurations[core]??'':''} ${configuration.replace(/^\[[A-Za-z]+\]/,'')}`;return[...expanded.matchAll(/(\d)([spdfg])(\d+)/g)].map(match=>({n:Number(match[1]),type:match[2],electrons:Number(match[3])})).sort((a,b)=>((a.n)+('spdfg'.indexOf(a.type)))-((b.n)+('spdfg'.indexOf(b.type)))||a.n-b.n)}
function orbitalModelMarkup(element,configuration){const orbitalLabels={s:['s'],p:['p<sub>x</sub>','p<sub>y</sub>','p<sub>z</sub>'],d:['d<sub>xy</sub>','d<sub>yz</sub>','d<sub>z²</sub>','d<sub>xz</sub>','d<sub>x²−y²</sub>'],f:['f₁','f₂','f₃','f₄','f₅','f₆','f₇'],g:['g₁','g₂','g₃','g₄','g₅','g₆','g₇','g₈','g₉']};const core=configuration.match(/^\[([A-Za-z]+)\]/)?.[1];const outerConfiguration=configuration.replace(/^\[[A-Za-z]+\]/,'');const subshells=[...outerConfiguration.matchAll(/(\d)([spdfg])(\d+)/g)].map(match=>({n:Number(match[1]),type:match[2],electrons:Number(match[3])}));const rows=subshells.map(item=>{const labels=orbitalLabels[item.type];const orbitals=labels.length;const boxes=labels.map((label,index)=>{const up=index<Math.min(item.electrons,orbitals);const down=index<Math.max(0,item.electrons-orbitals);return`<span class="orbital-column"><span class="orbital-box"><i class="alpha-spin">${up?'↑':''}</i><i class="beta-spin">${down?'↓':''}</i></span><small>${label}</small></span>`}).join('');return`<span class="orbital-row"><strong>${item.n}${item.type}<sup>${item.electrons}</sup></strong><span class="orbital-boxes">${boxes}</span></span>`}).join('');const coreMarkup=core?`<span class="orbital-core"><small>Edelgaskern</small><strong>[${core}]</strong></span>`:'';return`<span class="orbital-model" role="img" aria-label="Orbitalbesetzung von ${element.name}${core?` mit Edelgaskern ${core}`:''}"><span class="orbital-spin-legend"><span><i class="alpha-spin">↑</i> α-Spin</span><span><i class="beta-spin">↓</i> β-Spin</span></span>${coreMarkup}<span class="orbital-levels">${rows}</span></span><span class="atom-caption">Orbitalbesetzung · ${element.symbol}</span>`}
const orbitalForms=[['s','s'],['px','p<sub>x</sub>'],['py','p<sub>y</sub>'],['pz','p<sub>z</sub>'],['dxy','d<sub>xy</sub>'],['dxz','d<sub>xz</sub>'],['dyz','d<sub>yz</sub>'],['dx2y2','d<sub>x²−y²</sub>'],['dz2','d<sub>z²</sub>']];
function orbitalShape(kind){const lobes=(rotation=0)=>`<g class="orbital-volume" transform="rotate(${rotation} 190 190)"><ellipse class="phase-positive" cx="249" cy="190" rx="57" ry="31"/><ellipse class="phase-negative" cx="131" cy="190" rx="57" ry="31"/></g>`;const dLobes=(rotation=0)=>`<g class="orbital-volume" transform="rotate(${rotation} 190 190)"><ellipse class="phase-positive" cx="235" cy="145" rx="45" ry="23" transform="rotate(-45 235 145)"/><ellipse class="phase-negative" cx="145" cy="145" rx="45" ry="23" transform="rotate(45 145 145)"/><ellipse class="phase-positive" cx="145" cy="235" rx="45" ry="23" transform="rotate(-45 145 235)"/><ellipse class="phase-negative" cx="235" cy="235" rx="45" ry="23" transform="rotate(45 235 235)"/></g>`;if(kind==='s')return`<g class="orbital-volume"><circle class="s-orbital" cx="190" cy="190" r="103"/><circle class="s-highlight" cx="160" cy="157" r="30"/></g>`;if(kind==='px')return lobes(0);if(kind==='py')return lobes(-38);if(kind==='pz')return lobes(90);if(kind==='dxy')return dLobes(0);if(kind==='dxz')return dLobes(-38);if(kind==='dyz')return dLobes(38);if(kind==='dx2y2')return dLobes(45);return`<g class="orbital-volume"><ellipse class="phase-positive" cx="190" cy="110" rx="34" ry="72"/><ellipse class="phase-negative" cx="190" cy="270" rx="34" ry="72"/><ellipse class="orbital-torus" cx="190" cy="190" rx="74" ry="25"/></g>`}
function orbitalQuantumNumbers(kind){const l=kind==='s'?0:kind.startsWith('p')?1:2;return{l,minShell:l+1}}
function orbitalFormsMarkup(element,kind,shell){const label=orbitalForms.find(item=>item[0]===kind)?.[1]??'s';const plainLabel=label.replace(/<[^>]+>/g,'');const{l}=orbitalQuantumNumbers(kind);const radialNodes=Math.max(0,shell-l-1);return`<canvas class="orbital-lab" data-kind="${kind}" data-shell="${shell}" role="img" aria-label="Interaktive Punktwolke und Grenzfläche des ${shell}${plainLabel}-Orbitals mit ${radialNodes} radialen Knoten"></canvas><span class="atom-caption">${shell}${label}-Orbital · ziehen zum Drehen</span>`}
let orbitalLabCleanup=()=>{};
function seededRandom(seed){let value=seed>>>0;return()=>((value=Math.imul(1664525,value)+1013904223>>>0)/4294967296)}
function gaussian(random){const u=Math.max(random(),1e-9),v=random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function orbitalPoints(kind,shell,count=1600){const random=seededRandom(shell*997+kind.split('').reduce((sum,char)=>sum+char.charCodeAt(0),0));const points=[];const type=kind[0],l=type==='s'?0:type==='p'?1:2,nodes=Math.max(0,shell-l-1);while(points.length<count){let x,y,z,phase=1;if(type==='s'){x=gaussian(random);y=gaussian(random);z=gaussian(random)}else if(type==='p'){const sign=random()<.5?-1:1;const axial=.55+Math.abs(gaussian(random));x=sign*axial;y=gaussian(random)*.34;z=gaussian(random)*.34;phase=sign;if(kind==='py')[x,y]=[y,x];if(kind==='pz')[x,z]=[z,x]}else if(kind==='dz2'){const axial=random()<.68;if(axial){const sign=random()<.5?-1:1;x=gaussian(random)*.3;y=gaussian(random)*.3;z=sign*(.55+Math.abs(gaussian(random)));phase=sign}else{const angle=random()*Math.PI*2;x=Math.cos(angle)*(1+gaussian(random)*.16);y=Math.sin(angle)*(1+gaussian(random)*.16);z=gaussian(random)*.13;phase=-1}}else{const quadrant=Math.floor(random()*4),angle=Math.PI/4+quadrant*Math.PI/2;x=Math.cos(angle)*(1+gaussian(random)*.25);y=Math.sin(angle)*(1+gaussian(random)*.25);z=gaussian(random)*.26;phase=quadrant%2? -1:1;const rotations={dxy:0,dxz:-.62,dyz:.62,dx2y2:Math.PI/4};const rotation=rotations[kind]??0;const nextX=x*Math.cos(rotation)-z*Math.sin(rotation);z=x*Math.sin(rotation)+z*Math.cos(rotation);x=nextX}const radius=Math.hypot(x,y,z);if(nodes&&Array.from({length:nodes},(_,index)=>(index+1)*1.35/(nodes+1)).some(node=>Math.abs(radius-node)<.1))continue;points.push({x,y,z,phase})}return points}
function setupOrbitalLab(canvas,state){orbitalLabCleanup();const context=canvas.getContext('2d'),points=orbitalPoints(canvas.dataset.kind,Number(canvas.dataset.shell));let yaw=.45,pitch=-.28,drag=false,lastX=0,lastY=0,frame=0,running=state.animated;const resize=()=>{const rect=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(rect.width*ratio));canvas.height=Math.max(1,Math.round(rect.height*ratio));context.setTransform(ratio,0,0,ratio,0,0);draw()};const project=point=>{const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);const x=point.x*cy-point.z*sy,z1=point.x*sy+point.z*cy;return{x,y:point.y*cp-z1*sp,z:point.y*sp+z1*cp,phase:point.phase}};function draw(){const width=canvas.clientWidth,height=canvas.clientHeight;context.clearRect(0,0,width,height);context.fillStyle='rgba(250,250,245,.42)';context.fillRect(0,0,width,height);const centerX=width/2,centerY=height/2,scale=Math.min(width,height)*(.19+Number(canvas.dataset.shell)*.006),blend=state.blend/100,extent=.72+state.probability/320,visibleCount=Math.round(points.length*state.probability/100);const projected=points.slice(0,visibleCount).map(project).filter(point=>!state.section||Math.abs(point.z-state.sectionPosition/55)<.16).sort((a,b)=>a.z-b.z);context.globalCompositeOperation='source-over';if(blend>.02){for(const point of projected){context.beginPath();context.fillStyle=point.phase>0?`rgba(216,139,83,${.012+blend*.035})`:`rgba(102,143,177,${.012+blend*.035})`;context.arc(centerX+point.x*scale*extent,centerY+point.y*scale*extent,4+blend*7,0,Math.PI*2);context.fill()}}if(blend<.98){for(const point of projected){context.beginPath();context.fillStyle=point.phase>0?`rgba(176,82,38,${.28+(1-blend)*.55})`:`rgba(48,95,132,${.28+(1-blend)*.55})`;context.arc(centerX+point.x*scale*extent,centerY+point.y*scale*extent,1.1+(1-blend)*1.2,0,Math.PI*2);context.fill()}}context.strokeStyle='rgba(33,54,51,.22)';context.lineWidth=1.2;context.beginPath();context.moveTo(centerX-width*.38,centerY);context.lineTo(centerX+width*.38,centerY);context.moveTo(centerX,centerY-height*.38);context.lineTo(centerX,centerY+height*.38);context.stroke();if(state.nodes){const{l}=orbitalQuantumNumbers(canvas.dataset.kind),nodes=Math.max(0,Number(canvas.dataset.shell)-l-1);context.setLineDash([4,5]);context.strokeStyle='rgba(33,54,51,.55)';for(let index=0;index<nodes;index++){context.beginPath();context.arc(centerX,centerY,(index+1)*scale*1.35/(nodes+1),0,Math.PI*2);context.stroke()}context.setLineDash([])}context.beginPath();context.fillStyle='#213633';context.arc(centerX,centerY,4,0,Math.PI*2);context.fill()};const tick=()=>{if(running){yaw+=.0025;draw();frame=requestAnimationFrame(tick)}};canvas.onpointerdown=event=>{event.stopPropagation();drag=true;lastX=event.clientX;lastY=event.clientY;canvas.setPointerCapture(event.pointerId)};canvas.onpointermove=event=>{if(!drag)return;yaw+=(event.clientX-lastX)*.009;pitch=Math.max(-1.3,Math.min(1.3,pitch+(event.clientY-lastY)*.009));lastX=event.clientX;lastY=event.clientY;draw()};canvas.onpointerup=event=>{event.stopPropagation();drag=false};canvas.onclick=event=>event.stopPropagation();const observer=new ResizeObserver(resize);observer.observe(canvas);resize();if(running)tick();orbitalLabCleanup=()=>{cancelAnimationFrame(frame);observer.disconnect()};return{draw,setRunning(value){running=value;cancelAnimationFrame(frame);if(running)tick()}}}
function activateVisualToggle(button,info,element,configuration,factsMarkup){
  let modelVisible=false,activeModel='bohr',activeOrbital='s',activeShell=1,labController=null;
  const subshells=expandedSubshells(configuration),occupiedTypes=new Set(subshells.filter(item=>item.electrons>0).map(item=>item.type)),occupiedSubshells=new Set(subshells.filter(item=>item.electrons>0).map(item=>`${item.n}${item.type}`));
  const labState={blend:58,probability:90,nodes:true,section:false,sectionPosition:0,animated:false};
  const renderModel=()=>{
    orbitalLabCleanup();button.innerHTML=activeModel==='orbital'?orbitalModelMarkup(element,configuration):activeModel==='forms'?orbitalFormsMarkup(element,activeOrbital,activeShell):atomModelMarkup(element,configuration);
    const{minShell}=orbitalQuantumNumbers(activeOrbital);const shellControls=Array.from({length:8-minShell},(_,index)=>index+minShell).map(shell=>`<button type="button" data-shell="${shell}" class="orbital-form-button ${shell===activeShell?'is-active':''} ${occupiedSubshells.has(`${shell}${activeOrbital[0]}`)?'is-occupied':''}" aria-pressed="${shell===activeShell}">${shell}</button>`).join('');
    const labControls=`<div class="orbital-lab-controls"><label>Darstellung <input data-lab="blend" type="range" min="0" max="100" value="${labState.blend}"><span>Punkte ↔ Grenzfläche</span></label><label>Wahrscheinlichkeitsniveau <input data-lab="probability" type="range" min="70" max="95" value="${labState.probability}"><span data-lab-value="probability">${labState.probability} %</span></label><label class="lab-check"><input data-lab="nodes" type="checkbox" ${labState.nodes?'checked':''}> Knoten anzeigen</label><label class="lab-check"><input data-lab="section" type="checkbox" ${labState.section?'checked':''}> Schnittansicht</label><label class="lab-section-position">Schnittebene <input data-lab="sectionPosition" type="range" min="-50" max="50" value="${labState.sectionPosition}" ${labState.section?'':'disabled'}></label><div class="lab-actions"><button data-lab="animate" type="button">${labState.animated?'Animation stoppen':'Animation starten'}</button><button data-return-facts type="button">Fachdaten anzeigen</button></div><small>Jeder Punkt steht für einen möglichen Messort – nicht für eine Elektronenbahn. Die Grenzfläche ist eine schematische Wahrscheinlichkeitsgrenze.</small></div>`;
    const formControls=activeModel==='forms'?`<div class="orbital-form-controls"><span>Orbitalform</span><div>${orbitalForms.map(([value,label])=>`<button type="button" data-orbital="${value}" class="orbital-form-button ${value===activeOrbital?'is-active':''} ${occupiedTypes.has(value[0])?'is-occupied':''}" aria-pressed="${value===activeOrbital}">${label}</button>`).join('')}</div><span>Schale · Hauptquantenzahl n</span><div>${shellControls}</div>${labControls}<p><i class="phase-key positive"></i><i class="phase-key negative"></i> Farben kennzeichnen die beiden Phasen der Wellenfunktion.</p></div>`:'';
    info.innerHTML=`<h2>Element ${element.number}</h2><div class="model-options" aria-label="Atommodelle"><span class="model-options-label">Atommodelle</span><button class="model-option ${activeModel==='bohr'?'is-active':''}" data-model="bohr" type="button" aria-pressed="${activeModel==='bohr'}"><span class="model-option-icon bohr-icon" aria-hidden="true"></span><span>Bohrsches Atommodell</span></button><button class="model-option ${activeModel==='orbital'?'is-active':''}" data-model="orbital" type="button" aria-pressed="${activeModel==='orbital'}"><span class="model-option-icon orbital-icon" aria-hidden="true"></span><span>Orbitalbesetzung</span></button><button class="model-option ${activeModel==='forms'?'is-active':''}" data-model="forms" type="button" aria-pressed="${activeModel==='forms'}"><span class="model-option-icon forms-icon" aria-hidden="true"></span><span>Orbitalformen</span></button>${formControls}</div>`;
    info.querySelectorAll('[data-model]').forEach(option=>option.onclick=()=>{activeModel=option.dataset.model;renderModel()});info.querySelectorAll('[data-orbital]').forEach(option=>option.onclick=()=>{activeOrbital=option.dataset.orbital;activeShell=Math.max(activeShell,orbitalQuantumNumbers(activeOrbital).minShell);renderModel()});info.querySelectorAll('[data-shell]').forEach(option=>option.onclick=()=>{activeShell=Number(option.dataset.shell);renderModel()});
    if(activeModel==='forms'){labController=setupOrbitalLab(button.querySelector('.orbital-lab'),labState);info.querySelector('[data-return-facts]').onclick=()=>{activeModel='bohr';modelVisible=false;orbitalLabCleanup();button.classList.remove('shows-atom');detail.classList.remove('shows-atom');button.setAttribute('aria-pressed','false');button.innerHTML=elementTileMarkup(element);info.innerHTML=factsMarkup};info.querySelectorAll('[data-lab]').forEach(control=>{if(control.dataset.lab==='animate'){control.onclick=()=>{labState.animated=!labState.animated;control.textContent=labState.animated?'Animation stoppen':'Animation starten';labController.setRunning(labState.animated)};return}control.oninput=()=>{const key=control.dataset.lab;labState[key]=control.type==='checkbox'?control.checked:Number(control.value);if(key==='section')info.querySelector('[data-lab="sectionPosition"]').disabled=!labState.section;if(key==='probability')info.querySelector('[data-lab-value="probability"]').textContent=`${labState.probability} %`;labController.draw()}})}
  };
  button.onclick=()=>{if(modelVisible&&activeModel==='forms')return;modelVisible=!modelVisible;button.classList.toggle('shows-atom',modelVisible);detail.classList.toggle('shows-atom',modelVisible);button.setAttribute('aria-pressed',String(modelVisible));button.setAttribute('aria-label',modelVisible?`Elementkachel und Fachdaten von ${element.name} anzeigen`:`Atommodelle von ${element.name} anzeigen`);if(modelVisible)renderModel();else{orbitalLabCleanup();button.innerHTML=elementTileMarkup(element);info.innerHTML=factsMarkup}};
}
function bodyClass(element){if([1,6,7,8].includes(element.number))return'basic';if([11,12,15,16,17,19,20].includes(element.number))return'bulk';if([9,25,26,27,28,29,30,34,42,53].includes(element.number))return'trace';if([5,14,23,24,33,35,37,50,82].includes(element.number))return'disputed';return'none'}
function lifeClass(element){if([1,6,7,8,12,15,16,19,20,25,26,29,30,42].includes(element.number))return'universal';if([11,17,27,33,34,53].includes(element.number))return'human';if([9,14,23,24,28].includes(element.number))return'likely-human';if([5,56].includes(element.number))return'species';if([3,35,37,48,50,82].includes(element.number))return'suspected-human';if(element.number===74)return'suspected';return'none'}
function abundanceClass(value){if(!Number.isFinite(value))return'unknown';if(value>10)return'gt10';if(value>1)return'gt1';if(value>.1)return'gt-1';if(value>.01)return'gt-2';if(value>.001)return'gt-3';if(value>.0001)return'gt-4';if(value>.00001)return'gt-5';if(value>.000001)return'gt-6';if(value>.0000001)return'gt-7';return'gt-8'}
function abundanceFor(view,number){return abundanceData?.[view.replace('abundance-','')]?.[number]}
function densityClass(value){if(!Number.isFinite(value))return'unknown';if(value>=20)return'd6';if(value>=10)return'd5';if(value>=5)return'd4';if(value>=2)return'd3';if(value>=1)return'd2';if(value>=.1)return'd1';return'd0'}
function discoveryClass(value){if(value==='Ancient')return'ancient';const year=Number(value);if(!Number.isFinite(year))return'unknown';if(year<1750)return'pre1750';if(year<1850)return'y1750';if(year<1900)return'y1850';if(year<1950)return'y1900';if(year<2000)return'y1950';return'y2000'}
function originGradient(number){const values=originData?.elements?.[number]??{human:100};let position=0;const stops=[];for(const [key,value] of Object.entries(values)){const color=originPalette[key]?.[1]??'#c9c9c3';stops.push(`${color} ${position}%`,`${color} ${position+value}%`);position+=value}return`linear-gradient(to bottom,${stops.join(',')})`}
function originSummary(number){const values=originData?.elements?.[number]??{human:100};return Object.entries(values).map(([key,value])=>`${value.toLocaleString('de-DE')} % ${originPalette[key]?.[0]??key}`).join(' · ')}
function electronegativityClass(value,isMulliken=false){if(!Number.isFinite(value))return'unknown';const limits=isMulliken?[2.5,3.5,4.5,5.5,7]:[1,1.5,2,2.5,3];return`e${limits.findIndex(limit=>value<limit)===-1?5:limits.findIndex(limit=>value<limit)}`}
function resistivityClass(value){if(!Number.isFinite(value))return'unknown';if(value<3e-8)return'r0';if(value<1e-7)return'r1';if(value<1e-6)return'r2';if(value<1e-3)return'r3';if(value<1)return'r4';return'r5'}
function electronicValue(view,number){if(view==='electronegativity-pauling')return electronicData?.pauling?.[number];if(view==='electronegativity-allred')return electronicData?.allredRochow?.[number];if(view==='electronegativity-mulliken')return electronicData?.mullikenEv?.[number];if(view==='resistivity')return electronicData?.resistivityOhmM?.[number]}
function syncDiscoveryWidth(){discoveryControls.style.width=`${Math.min(table.scrollWidth,tableView.clientWidth)}px`}
function updateDiscoveryDisplay(){if(settings.view!=='discovery')return;const index=Math.max(0,Math.min(discoveryYears.length-1,Number(settings.discoveryIndex)||0));settings.discoveryIndex=index;discoverySlider.value=index;const selected=discoveryYears[index];const today=index===discoveryYears.length-1;discoveryValue.textContent=selected==='Ancient'?'Antike':today?'Heute':String(selected);let known=0,newCount=0;document.querySelectorAll('.element').forEach((button,elementIndex)=>{const discovered=substanceData?.discovery?.[elements[elementIndex].number];const isKnown=selected==='Ancient'?discovered==='Ancient':today||discovered==='Ancient'||Number(discovered)<=selected;const isNew=!today&&(selected==='Ancient'?discovered==='Ancient':Number(discovered)===selected);button.dataset.discoveryStatus=isNew?'new':isKnown?'known':'future';if(isKnown)known++;if(isNew)newCount++});discoveryStatus.textContent=today?`Heute sind alle ${known} Elemente bekannt.`:`${newCount} ${newCount===1?'Element wird':'Elemente werden'} in dieser Stufe neu sichtbar · ${known} insgesamt bekannt.`}
function renderLegendItems(items){legend.innerHTML='';items.forEach(([label,color])=>{const item=document.createElement('span');item.style.setProperty('--element-color',color);item.innerHTML=`<i aria-hidden="true"></i>${label}`;legend.append(item)})}
function renderActiveLegend(){if(abundanceViews.includes(settings.view)){renderLegendItems(abundanceLegend);return}if(settings.view==='density'){renderLegendItems([['< 0,1 g/cm³','#dcebf0'],['0,1–< 1','#c7dfdf'],['1–< 2','#a9cfbf'],['2–< 5','#83b99d'],['5–< 10','#5b9a7d'],['10–< 20','#3f7567'],['≥ 20 g/cm³','#244d49'],['keine belastbaren Daten','#c9c9c3']]);return}if(settings.view==='discovery'){renderLegendItems([['in der gewählten Stufe neu entdeckt','#d5963f'],['zu diesem Zeitpunkt bereits bekannt','#b8cbc4'],['noch nicht entdeckt','#deded8']]);return}if(settings.view.startsWith('electronegativity-')){const labels=settings.view==='electronegativity-mulliken'?['< 2,5 eV','2,5–< 3,5','3,5–< 4,5','4,5–< 5,5','5,5–< 7','≥ 7 eV']:['< 1','1–< 1,5','1,5–< 2','2–< 2,5','2,5–< 3','≥ 3'];renderLegendItems([...labels.map((label,index)=>[label,['#d8e7ef','#b9d8e4','#8fc4d3','#62abbc','#377f99','#214f68'][index]]),['kein belastbarer Wert','#c9c9c3']]);return}if(settings.view==='resistivity'){renderLegendItems([['< 3·10⁻⁸ Ωm','#f0c83d'],['3·10⁻⁸–< 10⁻⁷','#d5aa3c'],['10⁻⁷–< 10⁻⁶','#af8845'],['10⁻⁶–< 10⁻³','#8a7458'],['10⁻³–< 1','#666777'],['≥ 1 Ωm','#3f4655'],['kein belastbarer Wert','#c9c9c3']]);return}renderLegend()}
const baseRenderActiveLegend=renderActiveLegend;
renderActiveLegend=function(){if(settings.view==='origin')renderLegendItems(Object.values(originPalette));else baseRenderActiveLegend()};
function tileMass(value){const parsed=Number(value);return Number.isFinite(parsed)?parsed.toLocaleString('de-DE',{maximumFractionDigits:2}):value}
function roundedTileMass(value){const parsed=Number(value);return Number.isFinite(parsed)?Math.ceil(parsed).toLocaleString('de-DE'):value}
function massCollides(button){const number=button.querySelector('.element-number'),mass=button.querySelector('.element-mass');if(getComputedStyle(number).display==='none'||getComputedStyle(mass).display==='none')return false;return number.getBoundingClientRect().right+2>mass.getBoundingClientRect().left}
function fitTileMasses(){document.querySelectorAll('.element').forEach(button=>{const mass=button.querySelector('.element-mass'),raw=mass.dataset.mass;mass.style.display='';mass.textContent=tileMass(raw);mass.classList.remove('is-rounded');if(!massCollides(button))return;mass.textContent=roundedTileMass(raw);mass.classList.add('is-rounded');if(massCollides(button))mass.style.display='none'})}
function hasSymbolNameCollision(){return[...document.querySelectorAll('.element')].some(button=>{const symbol=button.querySelector('.element-symbol'),name=button.querySelector('.element-name');if(getComputedStyle(name).display==='none')return false;return symbol.getBoundingClientRect().bottom+1>name.getBoundingClientRect().top})}
function hasRadioactivityCollision(){if(settings.tileMeta!=='radioactivity')return false;return[...document.querySelectorAll('.element[data-radioactive="true"]')].some(button=>{const number=button.querySelector('.element-number'),radioactivity=button.querySelector('.element-radioactivity'),symbol=button.querySelector('.element-symbol');if(getComputedStyle(number).display==='none'||getComputedStyle(radioactivity).display==='none')return false;const numberRect=number.getBoundingClientRect(),radioactivityRect=radioactivity.getBoundingClientRect(),symbolRect=symbol.getBoundingClientRect();return numberRect.right+2>radioactivityRect.left||radioactivityRect.bottom+1>symbolRect.top})}
function hasMetaSymbolCollision(){return[...document.querySelectorAll('.element')].some(button=>{const number=button.querySelector('.element-number'),mass=button.querySelector('.element-mass'),symbol=button.querySelector('.element-symbol');if(getComputedStyle(number).display==='none')return false;const metaBottom=Math.max(number.getBoundingClientRect().bottom,getComputedStyle(mass).display==='none'?0:mass.getBoundingClientRect().bottom);return metaBottom+1>symbol.getBoundingClientRect().top})}
function fitTileContent(){if(tableView.hidden||table.getClientRects().length===0)return;table.classList.remove('pse-hide-names','pse-hide-meta','pse-hide-radioactivity');fitTileMasses();const namesMustHide=hasSymbolNameCollision();if(namesMustHide)table.classList.add('pse-hide-names');if(hasRadioactivityCollision())table.classList.add('pse-hide-radioactivity');if(namesMustHide&&hasMetaSymbolCollision())table.classList.add('pse-hide-meta')}
function saveSettings(){localStorage.setItem(settingsKey,JSON.stringify(settings))}
function loadSettings(){try{const current=JSON.parse(localStorage.getItem(settingsKey));const legacy=!current?JSON.parse(localStorage.getItem(legacySettingsKey)):null;const stored=current??legacy;if(stored?.layout==='long')settings.layout='long';if(stored?.tileMeta==='radioactivity')settings.tileMeta='radioactivity';let storedView=stored?.view;if(legacy&&storedView==='family')storedView='traditional';if(storedView==='metalloid')storedView='material-class';if(['traditional','family','state','material-class','body','life','density','discovery','origin',...abundanceViews,...electronicViews].includes(storedView))settings.view=storedView;if(Number.isFinite(Number(stored?.temperature)))settings.temperature=Number(stored.temperature);if(Number.isFinite(Number(stored?.pressure))&&Number(stored.pressure)>=0)settings.pressure=Number(stored.pressure);if(Number.isFinite(Number(stored?.discoveryIndex)))settings.discoveryIndex=Math.max(0,Math.min(discoveryYears.length-1,Number(stored.discoveryIndex)));if(legacy)saveSettings()}catch{}}
function renderViewOptions(){viewOptions.innerHTML=viewGroups.map(group=>`<p class="view-group-title">${group.title}</p>${group.items.map(([value,label,enabled=false])=>`<label class="view-option"><input type="radio" name="view" value="${value}" ${value===settings.view?'checked':''} ${enabled?'':'disabled'}><span>${label}${enabled?'':'<small>Daten folgen</small>'}</span></label>`).join('')}`).join('')}
function loadNameMode(){try{if(JSON.parse(localStorage.getItem(settingsKey))?.nameMode==='origin')settings.nameMode='origin'}catch{}}
function shortPosition(element){return{row:element.gridRow,column:element.gridColumn}}
function longPosition(element){if(element.period===1)return{row:2,column:element.number===1?1:32};if(element.period===2||element.period===3)return{row:element.period+1,column:element.group<=2?element.group:element.group+14};if(element.period===4||element.period===5)return{row:element.period+1,column:element.group<=2?element.group:element.group+14};if(element.period===6)return{row:7,column:element.number-54};return{row:8,column:element.number-86}}
function renderGroupNumbers(){table.querySelectorAll('.group-number').forEach(node=>node.remove());const labels=settings.layout==='long'?[{value:1,column:1},{value:2,column:2},...Array.from({length:16},(_,index)=>({value:index+3,column:index+17}))]:Array.from({length:18},(_,index)=>({value:index+1,column:index+1}));labels.forEach(item=>{const label=document.createElement('span');label.className='group-number';label.style.gridColumn=item.column;label.style.gridRow=1;label.textContent=item.value;table.prepend(label)})}
function renderLegend(){legend.innerHTML='';let items;if(settings.view==='state'){items=[['fest','#d8c8b9'],['flüssig','#9fc8cf'],['gasförmig','#c7d8e5'],['unbekannt','#d8d8d0']]}else if(settings.view==='material-class'){items=[['Metalle','#63b5d2'],['Halbmetalle','#d45b96'],['Nichtmetalle','#ead758']]}else if(settings.view==='family'){items=[['Alkalimetalle','#4c91be'],['Erdalkalimetalle','#65b9d5'],['Chalkogene','#e8a35c'],['Halogene','#df4f97'],['Edelgase','#84609a'],['Seltene Erden · Lanthanoide','#68af58'],['Actinoide','#67b4d2'],['Platinmetalle','#a8ba38'],['Münzmetalle','#dfc82e'],['weitere Elemente','#e4e2dc']]}else if(settings.view==='body'){items=[['Grundelemente des Lebens · 97 % der Körpermasse','#56b33e'],['Mengenelemente','#e84a4d'],['Spurenelemente · biologische Funktion','#efd72f'],['Spurenelemente · Funktion umstritten','#42acd2'],['keine bekannte biologische Funktion','#deded8']]}else if(settings.view==='life'){items=[['essenziell für alle untersuchten Spezies','#e83f4b'],['essenziell für den Menschen','#ee8a34'],['für mindestens eine Spezies, vermutlich für Menschen','#efd72f'],['essenziell für mindestens eine Spezies','#57b449'],['biologische Funktion vermutet','#48b5cf'],['Funktion vermutet, vermutlich für Menschen essenziell','#3b91c6'],['keine bekannte biologische Funktion','#deded8']]}else{items=categories.map(category=>{const element=elements.find(item=>item.category===category);return element?[element.categoryName,getComputedStyle(document.documentElement).getPropertyValue(`--${category}`)]:null}).filter(Boolean)}items.forEach(([label,color])=>{const item=document.createElement('span');if(color)item.style.setProperty('--element-color',color);item.innerHTML=`<i aria-hidden="true"></i>${label}`;legend.append(item)})}
function applyLayout(value,{persist=true}={}){settings.layout=value==='long'?'long':'short';table.classList.toggle('is-long',settings.layout==='long');document.querySelectorAll('.element').forEach((button,index)=>{const position=settings.layout==='long'?longPosition(elements[index]):shortPosition(elements[index]);button.style.gridRow=position.row;button.style.gridColumn=position.column});renderGroupNumbers();document.querySelectorAll('.series-label').forEach(label=>label.hidden=settings.layout==='long');document.querySelector(`input[name="layout"][value="${settings.layout}"]`).checked=true;if(persist)saveSettings();scheduleTileFit()}
function applyTileMeta(value,{persist=true}={}){settings.tileMeta=value==='radioactivity'?'radioactivity':'mass';table.dataset.tileMeta=settings.tileMeta;const input=document.querySelector(`input[name="tileMeta"][value="${settings.tileMeta}"]`);if(input)input.checked=true;if(persist)saveSettings();scheduleTileFit()}
function applyNameMode(value,{persist=true}={}){settings.nameMode=value==='origin'?'origin':'german';document.querySelectorAll('.element-name').forEach((node,index)=>node.textContent=tileName(elements[index]));const input=document.querySelector(`input[name="nameMode"][value="${settings.nameMode}"]`);if(input)input.checked=true;if(persist)saveSettings();scheduleTileFit()}
function adjustedBoilingPoint(boilingK,pressureHpa){if(!Number.isFinite(boilingK)||!Number.isFinite(pressureHpa)||pressureHpa<=0)return null;const reference=phaseData?.referencePressureHpa??1013.25;const denominator=(1/boilingK)-(8.314/85000)*Math.log(pressureHpa/reference);return denominator>0?1/denominator:null}
function phaseAt(element,temperatureC,pressureHpa){const values=phaseData?.elements?.[element.number];if(!values)return'unbekannt';const temperatureK=Math.max(0,temperatureC+273.15);if(element.number===2&&pressureHpa<25300){if(pressureHpa===0)return temperatureK===0?'flüssig':'gasförmig';const heliumBoiling=adjustedBoilingPoint(values.boilingK,pressureHpa);return Number.isFinite(heliumBoiling)&&temperatureK>=heliumBoiling?'gasförmig':'flüssig'}const triplePointPressure={6:108000,33:36300}[element.number];if(triplePointPressure&&pressureHpa<triplePointPressure){const sublimation=adjustedBoilingPoint(values.boilingK,pressureHpa)??values.boilingK;return Number.isFinite(sublimation)?(temperatureK<sublimation?'fest':'gasförmig'):'unbekannt'}const melting=values.meltingK;const boiling=adjustedBoilingPoint(values.boilingK,pressureHpa);if(Number.isFinite(melting)&&Number.isFinite(boiling)&&boiling<=melting)return temperatureK<boiling?'fest':'gasförmig';if(Number.isFinite(melting)&&temperatureK<melting)return'fest';if(Number.isFinite(boiling)&&temperatureK>=boiling)return'gasförmig';if(Number.isFinite(melting)&&Number.isFinite(boiling)&&temperatureK>=melting&&temperatureK<boiling)return'flüssig';return'unbekannt'}
function updatePhaseDisplay(){if(settings.view!=='state')return;let unknown=0;document.querySelectorAll('.element').forEach((button,index)=>{const state=phaseAt(elements[index],settings.temperature,settings.pressure);button.dataset.state=state;if(state==='unbekannt')unknown++});const pressureHint=settings.pressure<100||settings.pressure>2000?' Außerhalb von 100–2000 hPa ist die Drucknäherung nur eingeschränkt belastbar.':'';phaseStatus.textContent=`Berechnet für ${settings.temperature.toLocaleString('de-DE')} °C und ${settings.pressure.toLocaleString('de-DE')} hPa. ${unknown} Elemente ohne ausreichende Phasendaten.${pressureHint}`}
function syncPhaseControls(){temperatureInput.value=settings.temperature;pressureInput.value=settings.pressure;phaseControls.hidden=settings.view!=='state';updatePhaseDisplay()}
function syncDiscoveryControls(){discoveryControls.hidden=settings.view!=='discovery';if(settings.view==='discovery'){updateDiscoveryDisplay();requestAnimationFrame(syncDiscoveryWidth)}}
function applyView(value,{persist=true}={}){settings.view=['traditional','family','state','material-class','body','life','density','discovery','origin',...abundanceViews,...electronicViews].includes(value)?value:'traditional';table.dataset.view=settings.view;tableView.dataset.view=settings.view;periodicTableTitle.textContent=viewTitles[settings.view]??'Herkömmliche Darstellung';document.querySelectorAll('.element').forEach((button,index)=>button.title=settings.view==='origin'?originSummary(elements[index].number):'');if(settings.view==='origin')document.querySelectorAll('.element').forEach((button,index)=>button.style.setProperty('--origin-background',originGradient(elements[index].number)));if(abundanceViews.includes(settings.view))document.querySelectorAll('.element').forEach((button,index)=>button.dataset.abundance=abundanceClass(abundanceFor(settings.view,elements[index].number)));if(electronicViews.includes(settings.view))document.querySelectorAll('.element').forEach((button,index)=>{const value=electronicValue(settings.view,elements[index].number);button.dataset.electronic=settings.view==='resistivity'?resistivityClass(value):electronegativityClass(value,settings.view==='electronegativity-mulliken')});renderActiveLegend();syncPhaseControls();syncDiscoveryControls();const input=document.querySelector(`input[name="view"][value="${settings.view}"]`);if(input)input.checked=true;if(persist)saveSettings()}
function showTable(){orbitalLabCleanup();document.querySelector('.app-head').hidden=false;detailView.hidden=true;tableView.hidden=false;history.replaceState(null,'',location.pathname);table.classList.remove('pse-hide-names','pse-hide-meta');requestAnimationFrame(()=>requestAnimationFrame(()=>{fitTileContent();if(settings.view==='discovery')syncDiscoveryWidth();document.querySelector(`[data-number="${detail.dataset.number}"]`)?.focus({preventScroll:true})}))}
function showElement(element,updateUrl=true){
  orbitalLabCleanup();
  document.querySelector('.app-head').hidden=true;
  tableView.hidden=true;detailView.hidden=false;detail.dataset.number=element.number;detail.classList.remove('shows-atom');
  const group=element.group??'–';
  const density=substanceData?.density?.[element.number];const discovery=substanceData?.discovery?.[element.number];
  const chemistry=detailData?.[element.number]??{};
  const pauling=electronicData?.pauling?.[element.number];
  const radioactive=isRadioactiveElement(element);
  const halfLife=halfLifeData?.[element.number];
  const electronConfiguration=(chemistry.electronConfiguration??'–').replace(/([spdfg])(\d+)/g,'$1<sup>$2</sup>');
  const isotopeFacts=radioactive?`<div><dt>Radioaktivität</dt><dd>Kein stabiles Isotop</dd></div><div><dt>Langlebigstes Isotop · Halbwertszeit</dt><dd>${halfLife?`${halfLife[0]} · ${halfLife[1]}`:'–'}</dd></div>`:`<div class="fact-wide"><dt>Isotope</dt><dd>Stabile Isotope vorhanden</dd></div>`;
  const factsMarkup=`<h2 tabindex="-1">Element ${element.number}</h2><div class="detail-facts"><section><h3>Grunddaten</h3><dl><div><dt>Symbol</dt><dd>${symbolOrigin(element)}</dd></div><div><dt>Ordnungszahl</dt><dd>${element.number}</dd></div><div><dt>Atommasse</dt><dd>${element.mass} u</dd></div><div><dt>Gruppe</dt><dd>${group}</dd></div><div><dt>Periode</dt><dd>${element.period}</dd></div></dl></section><section><h3>Stoffeigenschaften</h3><dl><div><dt>Elementkategorie</dt><dd>${element.categoryName}</dd></div><div><dt>Aggregatzustand</dt><dd>${element.state}</dd></div><div><dt>Dichte</dt><dd>${Number.isFinite(density)?`${density.toLocaleString('de-DE')} g/cm³`:'–'}</dd></div><div><dt>Entdeckung</dt><dd>${discovery==='Ancient'?'Antike':discovery??'–'}</dd></div>${isotopeFacts}</dl></section><section><h3>Chemisches Verhalten</h3><dl><div><dt>Elektronegativität (Pauling)</dt><dd>${Number.isFinite(pauling)?pauling.toLocaleString('de-DE'):'–'}</dd></div><div><dt>Oxidationszahlen</dt><dd>${chemistry.oxidationStates||'–'}</dd></div><div class="fact-wide configuration-fact"><dt>Elektronenkonfiguration</dt><dd>${electronConfiguration}</dd></div></dl></section><section><h3>Kosmischer Ursprung</h3><dl><div class="fact-wide"><dt>Anteile im Sonnensystem</dt><dd>${originSummary(element.number)}</dd></div></dl></section><p class="facts-note">Stoffdaten bei Standardbedingungen, soweit nicht anders angegeben. Herkunftsanteile sind wissenschaftliche Modellschätzungen.</p></div>`;
  detail.innerHTML=`<button class="detail-tile detail-visual-toggle ${categoryClass(element)}" type="button" aria-pressed="false" aria-label="Bohrsches Schalenmodell von ${element.name} anzeigen">${elementTileMarkup(element)}</button><div class="detail-info">${factsMarkup}</div>`;
  activateVisualToggle(detail.querySelector('.detail-visual-toggle'),detail.querySelector('.detail-info'),element,chemistry.electronConfiguration??'',factsMarkup);
  if(updateUrl)history.replaceState(null,'',`?element=${encodeURIComponent(element.symbol)}`);
  requestAnimationFrame(()=>detail.querySelector('h2')?.focus({preventScroll:true}));
}
function render(){
  discoverySlider.max=discoveryYears.length-1;
  const labels=[{row:7,text:'57–71',category:'lanthanide'},{row:8,text:'89–103',category:'actinide'}];
  labels.forEach(item=>{const node=document.createElement('span');node.className=`series-label category-${item.category}`;node.style.gridColumn='3';node.style.gridRow=item.row;node.textContent=item.text;table.append(node)});
  elements.forEach(element=>{const button=document.createElement('button');button.type='button';button.className=`element ${categoryClass(element)}`;button.dataset.number=element.number;button.dataset.state=element.state;button.dataset.material=materialClass(element);button.dataset.family=familyClass(element);button.dataset.body=bodyClass(element);button.dataset.life=lifeClass(element);button.dataset.density=densityClass(substanceData?.density?.[element.number]);button.dataset.discovery=discoveryClass(substanceData?.discovery?.[element.number]);button.dataset.radioactive=isRadioactiveElement(element)?'true':'false';button.setAttribute('aria-label',`${element.name}, Ordnungszahl ${element.number}${isRadioactiveElement(element)?', radioaktiv':''}`);button.innerHTML=`<span class="element-number">${element.number}</span><span class="element-mass" data-mass="${element.mass}">${tileMass(element.mass)}</span><span class="element-radioactivity" title="Radioaktives Element" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="2.1"/><path d="M10.4 8.4 7.15 2.8A10.4 10.4 0 0 1 16.85 2.8L13.6 8.4A4.2 4.2 0 0 0 10.4 8.4Z"/><path transform="rotate(120 12 12)" d="M10.4 8.4 7.15 2.8A10.4 10.4 0 0 1 16.85 2.8L13.6 8.4A4.2 4.2 0 0 0 10.4 8.4Z"/><path transform="rotate(240 12 12)" d="M10.4 8.4 7.15 2.8A10.4 10.4 0 0 1 16.85 2.8L13.6 8.4A4.2 4.2 0 0 0 10.4 8.4Z"/></svg></span><strong class="element-symbol">${element.symbol}</strong><span class="element-name">${element.name}</span>`;button.onclick=()=>showElement(element);table.append(button)});
  renderViewOptions();applyLayout(settings.layout,{persist:false});applyTileMeta(settings.tileMeta,{persist:false});applyNameMode(settings.nameMode,{persist:false});applyView(settings.view,{persist:false});
  scheduleTileFit();
  const requested=new URLSearchParams(location.search).get('element');if(requested){const found=elements.find(item=>item.symbol.toLowerCase()===requested.toLowerCase()||String(item.number)===requested);if(found)showElement(found,false)}
}
document.getElementById('backButton').onclick=showTable;
document.getElementById('infoButton').onclick=openViewInformation;
document.getElementById('settingsButton').onclick=()=>settingsDialog.showModal();
document.querySelectorAll('input[name="layout"]').forEach(input=>input.onchange=()=>applyLayout(input.value));
document.querySelectorAll('input[name="tileMeta"]').forEach(input=>input.onchange=()=>applyTileMeta(input.value));
document.querySelectorAll('input[name="nameMode"]').forEach(input=>input.onchange=()=>applyNameMode(input.value));
viewOptions.onchange=event=>{if(event.target.matches('input[name="view"]'))applyView(event.target.value)};
temperatureInput.oninput=()=>{const value=Number(temperatureInput.value);if(Number.isFinite(value)&&value>=-273.15){settings.temperature=value;updatePhaseDisplay();saveSettings()}};
pressureInput.oninput=()=>{const value=Number(pressureInput.value);if(Number.isFinite(value)&&value>=0){settings.pressure=value;updatePhaseDisplay();saveSettings()}};
discoverySlider.oninput=()=>{settings.discoveryIndex=Number(discoverySlider.value);updateDiscoveryDisplay();saveSettings()};
document.getElementById('earthSurfaceButton').onclick=()=>{settings.temperature=15;settings.pressure=1013.25;syncPhaseControls();saveSettings()};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!detailView.hidden)showTable()});
let resizeFrame=0,settleFrame=0;
function scheduleTileFit(){cancelAnimationFrame(resizeFrame);cancelAnimationFrame(settleFrame);resizeFrame=requestAnimationFrame(()=>{fitTileContent();settleFrame=requestAnimationFrame(()=>{fitTileContent();if(settings.view==='discovery')syncDiscoveryWidth()})})}
window.addEventListener('resize',scheduleTileFit);
try{
  const data=window.SCHOLA_PSE_DATA;
  if(!data||!Array.isArray(data.elements)||data.elements.length!==118)throw new Error('Elementdaten sind unvollständig.');
  elements=data.elements;
  loadSettings();loadNameMode();
  render();
}catch(error){
  console.error('PSE-Daten konnten nicht geladen werden.',error);
  document.getElementById('loadError').hidden=false;
  tableView.hidden=true;
}
